   259→  public static sendMedia = async (
   260→    roomId: string,
   261→    asset: Asset,
   262→    caption?: string,
   263→  ) => {
   264→    if (!asset?.uri) throw new Error("No uri found");
   265→    const room = MatrixCore.getRoom(roomId);
   266→    const timeline = await room.timeline();
   267→    if (!timeline) throw new Error("Timeline not found");
   268→
   269→    const type = asset.type ?? "image/jpeg";
   270→    const assetWidth = asset.width ?? 0;
   271→    const assetHeight = asset.height ?? 0;
   272→    const isVideo = type.startsWith("video/");
   273→
   274→    const fileSource: UploadParameters = {
   275→      source: new UploadSource.File({
   276→        filename: asset.uri.replace("file://", ""),
   277→      }),
   278→      caption: caption || undefined,
   279→      formattedCaption: undefined,
   280→      mentions: undefined,
   281→      inReplyTo: undefined,
   282→    };
   283→
   284→    if (isVideo) {
   285→      const videoHandle = timeline.sendVideo(
   286→        fileSource,
   287→        new UploadSource.File({ filename: asset.uri.replace("file://", "") }),
   288→        {
   289→          height: BigInt(assetHeight),
   290→          width: BigInt(assetWidth),
   291→          mimetype: type,
   292→          size: BigInt(asset.fileSize ?? 0),
   293→          duration: asset.duration ? Math.round(asset.duration * 1000) : 0,
   294→          thumbnailInfo: {
   295→            height: BigInt(assetHeight),
   296→            width: BigInt(assetWidth),
   297→            mimetype: type,
   298→            size: BigInt(asset.fileSize ?? 0),
   299→          },
   300→          thumbnailSource: undefined,
   301→          blurhash: "",
   302→        },
   303→      );
   304→      await videoHandle.join();
   305→    } else {
   306→      const imageHandle = timeline.sendImage(
   307→        fileSource,
   308→        new UploadSource.File({ filename: asset.uri.replace("file://", "") }),
   309→        {
   310→          height: BigInt(assetHeight),
   311→          width: BigInt(assetWidth),
   312→          mimetype: type,
   313→          size: BigInt(asset.fileSize ?? 0),
   314→          thumbnailInfo: {
   315→            height: BigInt(assetHeight),
   316→            width: BigInt(assetWidth),
   317→            mimetype: type,
   318→            size: BigInt(asset.fileSize ?? 0),
   319→          },
   320→          thumbnailSource: undefined,
   321→          blurhash: "",
   322→          isAnimated: false,
   323→        },
   324→      );
   325→      await imageHandle.join();
   326→    }
   327→  };
