    25→  onMemberPress?: (member: MemberDetailsPayload) => void;
    26→}
    27→
    28→const getEventType = (event: EventTimelineItem) => {
    29→  if (
    30→    event.content.tag === TimelineItemContent_Tags.RtcNotification ||
    31→    event.content.tag === TimelineItemContent_Tags.CallInvite
    32→  ) {
    33→    return "call";
    34→  }
    35→  if (event.content.tag === TimelineItemContent_Tags.State) {
    36→    const stateContent = event.content.inner.content;
    37→    // This was used to handle call events in older versions of the SDK. Might be useful in the future.
    38→    // if (
    39→    //   stateContent.tag === OtherState_Tags.Custom &&
    40→    //   stateContent.inner?.eventType === "org.matrix.msc3401.call.member"
    41→    // ) {
    42→    //   return "call";
    43→    // }
    44→
    45→    if (stateContent.tag.includes("Room")) return "room";
    46→  }
    47→
    48→  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    49→    const kind = event.content.inner.content.kind;
    50→    if (kind?.tag === MsgLikeKind_Tags.Message) {
    51→      const msgType = kind.inner.content.msgType;
    52→
    53→      if (msgType?.tag === MessageType_Tags.Text) {
    54→        return "text";
    55→      } else if (msgType?.tag === MessageType_Tags.Image) {
    56→        return "image";
    57→      } else if (msgType?.tag === MessageType_Tags.File) {
    58→        return "file";
    59→      } else if (msgType?.tag === MessageType_Tags.Video) {
    60→        return "video";
    61→      } else if (msgType?.tag === MessageType_Tags.Audio) {
    62→        return "audio";
    63→      } else if (msgType?.tag === MessageType_Tags.Other) {
    64→        return "other";
    65→      } else {
    66→        return "unkown";
    67→      }
    68→    }
    69→
    70→    if (kind?.tag === MsgLikeKind_Tags.UnableToDecrypt) {
    71→      return "unableToDecrypt";
    72→    }
    73→
    74→    if (kind?.tag === MsgLikeKind_Tags.Redacted) {
    75→      return "redacted";
    76→    }
    77→  }
    78→  if (event.content.tag === TimelineItemContent_Tags.RoomMembership) {
    79→    return "membership";
    80→  }
    81→  if (event.content.tag === TimelineItemContent_Tags.ProfileChange) {
    82→    return "profile";
    83→  }
    84→  return "unkown";
    85→};
    86→
    87→export const SingleMessageType: FC<Props> = ({
    88→  event,
    89→  isPreviousSameSender,
    90→  onMemberPress,
    91→}) => {
    92→  if (!event) return null;
    93→
    94→  switch (getEventType(event)) {
    95→    case "text": {
    96→      return (
    97→        <TextMessage
    98→          event={event}
    99→          isPreviousSameSender={isPreviousSameSender}
   100→          onMemberPress={onMemberPress}
   101→        />
   102→      );
   103→    }
   104→    case "image": {
   105→      return (
   106→        <ImageMessage
   107→          event={event}
   108→          isPreviousSameSender={isPreviousSameSender}
   109→          onMemberPress={onMemberPress}
   110→        />
   111→      );
   112→    }
   113→    case "audio": {
   114→      return (
   115→        <VoiceMessage
   116→          event={event}
   117→          isPreviousSameSender={isPreviousSameSender}
   118→          onMemberPress={onMemberPress}
   119→        />
   120→      );
   121→    }
   122→    case "video": {
   123→      return (
   124→        <VideoMessage
   125→          event={event}
   126→          isPreviousSameSender={isPreviousSameSender}
   127→          onMemberPress={onMemberPress}
   128→        />
   129→      );
   130→    }
   131→    case "file": {
   132→      return (
   133→        <FileMessage
   134→          event={event}
   135→          isPreviousSameSender={isPreviousSameSender}
   136→          onMemberPress={onMemberPress}
   137→        />
   138→      );
   139→    }
   140→    case "other": {
   141→      return <OtherMessage event={event} />;
   142→    }
   143→    case "call": {
   144→      return (
   145→        <CallMessage
   146→          event={event}
   147→          isPreviousSameSender={isPreviousSameSender}
   148→        />
   149→      );
   150→    }
   151→    case "membership": {
   152→      return <MembershipInfoMessage event={event} />;
   153→    }
   154→    case "profile": {
   155→      return <ProfileInfoMessage event={event} />;
   156→    }
   157→    case "room": {
   158→      return <RoomInfoMessage event={event} />;
   159→    }
   160→    case "unableToDecrypt": {
   161→      return <UnableToDecryptMessage event={event} />;
   162→    }
   163→    case "redacted": {
   164→      return (
   165→        <DeletedMessage
   166→          event={event}
   167→          isPreviousSameSender={isPreviousSameSender}
   168→          onMemberPress={onMemberPress}
   169→        />
   170→      );
   171→    }
   172→    default:
   173→      return null;
   174→  }
   175→};
