    35→function formatDuration(milliseconds: number) {
    36→  const totalSeconds = Math.max(0, Math.ceil(milliseconds / 1000));
    37→  const minutes = Math.floor(totalSeconds / 60);
    38→  const seconds = totalSeconds % 60;
    39→  return `${minutes}:${seconds.toString().padStart(2, "0")}`;
    40→}
