    67→    "inner" in event.eventOrTransactionId
    68→      ? "eventId" in event.eventOrTransactionId.inner
    69→        ? event.eventOrTransactionId.inner.eventId
    70→        : event.eventOrTransactionId.inner.transactionId
    71→      : String(event.timestamp);
