   112→      // If paused mid-track and not at the end, resume instead of restarting
   113→      if (currentMs > 0 && currentMs < duration) {
   114→        await resume();
   115→        return;
   116→      }
   117→
   118→      // Re-fetch the playback URL to ensure it's valid (temp files may be cleaned up)
   119→      if (!content?.source || !MatrixCore.instance) {
   120→        Toast.show({
   121→          type: "error",
   122→          text1: "Failed to fetch voice message.",
   123→        });
   124→        return;
   125→      }
   126→
   127→      const mediaHandle = await MatrixCore.instance.getMediaFile(
   128→        content?.source,
   129→        `voice-${eventId}.${content.info?.mimetype?.split("/")[1] ?? "m4a"}`,
   130→        content.info?.mimetype || "audio/m4a",
   131→        true, // useCache
   132→        undefined,
   133→      );
   134→
   135→      const filePath = mediaHandle.path();
   136→      const freshUrl = filePath.startsWith("file://")
   137→        ? filePath
   138→        : `file://${filePath}`;
   139→
   140→      await play(freshUrl, duration);
   141→    } catch (e) {
   142→      Toast.show({
   143→        type: "error",
   144→        text1: "Failed to play voice message.",
   145→      });
   146→      console.log(e);
   147→    } finally {
   148→      setIsLoading(false);
   149→    }
   150→  };
   151→
   152→  if (!content) return null;
   153→
   154→  return (
   155→    <Block
   156→      align={isUser ? "flex-end" : "flex-start"}
   157→      margins={{ marginTop: isPreviousSameSender ? 6 : 16 }}
   158→    >
   159→      <MessageSender
   160→        sender={sender}
   161→        isUser={isUser}
   162→        senderId={senderId}
   163→        isPreviousSameSender={isPreviousSameSender}
   164→        onMemberPress={onMemberPress}
   165→      />
   166→      <MessageLongPressWrapper
   167→        event={event}
   168→        content={getEventTextContent(event)}
   169→      >
   170→        <Block flexDirection={isUser ? "row-reverse" : "row"}>
   171→          <Block
   172→            paddings={12}
   173→            background={isUser ? Colors.primary : Colors.message}
   174→            border={{
   175→              borderRadius: 24,
   176→            }}
   177→            flexDirection={isUser ? "row-reverse" : "row"}
   178→            gap={{
   179→              row: 8,
   180→              col: 16,
   181→            }}
   182→            align="center"
   183→            width="100%"
   184→            maxWidth={maxWidth}
   185→            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
   186→          >
   187→            <Button.Wrapper
   188→              disabled={isLoading}
   189→              onPress={onTogglePlay}
   190→              style={styles.playButton}
   191→            >
   192→              {isLoading ? (
   193→                <Loading isFullScreen={false} />
   194→              ) : (
   195→                <Image
   196→                  source={
   197→                    isPlaying
   198→                      ? require("assets/icons/pause-big.png")
   199→                      : require("assets/icons/play.png")
   200→                  }
   201→                  tintColor={Colors.white}
   202→                />
   203→              )}
   204→            </Button.Wrapper>
   205→            <Block flex={1} gap={4}>
   206→              <Block
   207→                height={4}
   208→                background={Colors.white20}
   209→                border={{ borderRadius: 2 }}
   210→              >
   211→                <Block
   212→                  height={4}
   213→                  width={`${Math.min(100, Math.round((currentMs / duration) * 100))}%`}
   214→                  background={Colors.white50}
   215→                  border={{ borderRadius: 2 }}
   216→                />
   217→              </Block>
   218→              <Block flexDirection="row" justify="space-between">
   219→                <Text size={TextSize.tiny} color={Colors.white80}>
   220→                  {formatDuration(currentMs)}
   221→                </Text>
   222→                <Text size={TextSize.tiny} color={Colors.white50}>
   223→                  {formatDuration(duration)}
   224→                </Text>
   225→              </Block>
   226→            </Block>
   227→            <MessageTimestamp event={event} isUser={isUser} />
   228→          </Block>
   229→          <PinIndicator event={event} />
   230→        </Block>
   231→      </MessageLongPressWrapper>
   232→      <SeenBy seenBy={seenBy} messageWidth={messageWidth} />
   233→    </Block>
   234→  );
   235→};
